using ValveResourceFormat;using ValveResourceFormat.ResourceTypes;using ValveResourceFormat.Serialization.KeyValues;using ValveKeyValue;using System.Text.Json;
var root="work/body-ult-fix";var report=new List<object>();var targets=JsonSerializer.Deserialize<string[]>(File.ReadAllText(root+"/ult-particles.json"))!;
foreach(var name in targets){var rel="particles/abilities/baba/"+name+".vpcf_c";var src=root+"/installed/"+rel;if(!File.Exists(src))src=root+"/retail/"+rel;using var r=new Resource();r.Read(src);var kv=(KeyValuesOrNTRO)r.DataBlock!;var changes=new List<object>();Walk(kv.Data,"");if(changes.Count==0)continue;Save(src,root+"/stage/"+rel,kv);report.Add(new{path=rel,changes});
 void Walk(KVObject obj,string path){if(obj.IsCollection){foreach(var (key,v) in obj.Children.ToArray()){var at=path+"/"+key;if(v.IsArray&&key.Contains("Color")&&v.Count>=3&&v.Count<=4){var a=v.Values.Select(x=>x.ToDouble(null)).ToArray();var max=a.Take(3).Max();if(max>0&&(a[2]>a[1]*1.03||a[2]>a[0]*1.03)){var arr=KVObject.Array();var target=new[]{max,max*.84,max*.20};for(int i=0;i<a.Length;i++){var value=i<3?target[i]:a[i];if(max<=1)arr.Add((float)value);else arr.Add((int)Math.Round(value));}obj[key]=arr;changes.Add(new{field=at,before=a,after=arr.ToKV3String()});}}else Walk(v,at);}}else if(obj.IsArray){int i=0;foreach(var v in obj.Values)Walk(v,path+"/"+i++);}}
}
foreach(var (name,tint) in new[]{("wood",.70f),("metal",.60f)}){var rel="materials/models/naidan_props/park_"+name+".vmat_c";var src="work/lighting-sync/stage/"+rel;using var r=new Resource();r.Read(src);var kv=(KeyValuesOrNTRO)r.DataBlock!;var arr=KVObject.Array();foreach(var n in new[]{tint,tint,tint,0f})arr.Add(n);kv.Data["m_vectorParams"].Values.Single(x=>x["m_name"].ToString()=="g_vColorTint1")["m_value"]=arr;Save(src,root+"/stage/"+rel,kv);report.Add(new{path=rel,tint,originalTextureDetailRetained=true});}
File.WriteAllText(root+"/patch-report.json",JsonSerializer.Serialize(report,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("Patched "+report.Count+" particle/material resources");
void Save(string src,string dest,KeyValuesOrNTRO kv){Directory.CreateDirectory(Path.GetDirectoryName(dest)!);using var ms=new MemoryStream();kv.Serialize(ms);ReplaceData(src,dest,ms.ToArray());using var check=new Resource();check.Read(dest);if(((KeyValuesOrNTRO)check.DataBlock!).Data.ToKV3String()!=kv.Data.ToKV3String())throw new Exception("Roundtrip failed "+dest);}
static void ReplaceData(string input,string output,byte[] data){var raw=File.ReadAllBytes(input);int table=8+BitConverter.ToInt32(raw,8);int count=BitConverter.ToInt32(raw,12);using var ms=new MemoryStream();using var w=new BinaryWriter(ms);w.Write(raw,0,16);w.Write(new byte[count*12]);var entries=new List<(byte[] Tag,int At,int Len)>();for(int i=0;i<count;i++){int p=table+12*i;var tag=raw[p..(p+4)];int start=p+4+BitConverter.ToInt32(raw,p+4),length=BitConverter.ToInt32(raw,p+8);while(ms.Position%4!=0)w.Write((byte)0);int at=(int)ms.Position;var payload=System.Text.Encoding.ASCII.GetString(tag)=="DATA"?data:raw[start..(start+length)];w.Write(payload);entries.Add((tag,at,payload.Length));}ms.Position=0;w.Write((uint)ms.Length);ms.Position=8;w.Write(8);w.Write(count);for(int i=0;i<count;i++){int p=16+i*12;ms.Position=p;w.Write(entries[i].Tag);w.Write(entries[i].At-(p+4));w.Write(entries[i].Len);}File.WriteAllBytes(output,ms.ToArray());}
